def minFallingPathSum(arr):
    n = len(arr)
    if n == 1:
        return arr[0][0]

    # dp will store the minimum falling path sums for the current row
    dp = arr[0][:]

    for i in range(1, n):
        # Find the minimum and second minimum values and their indices in the current dp array
        min1_val, min1_idx = float('inf'), -1
        min2_val = float('inf')

        for j in range(n):
            if dp[j] < min1_val:
                min2_val = min1_val
                min1_val = dp[j]
                min1_idx = j
            elif dp[j] < min2_val:
                min2_val = dp[j]

        new_dp = [0] * n
        for j in range(n):
            if j != min1_idx:
                new_dp[j] = arr[i][j] + min1_val
            else:
                new_dp[j] = arr[i][j] + min2_val
        dp = new_dp

    return min(dp)

