    memo = {}

    def dp(h, w):
        if h > w:
            h, w = w, h
        if h == 0 or w == 0:
            return 0
        if h == w:
            return 1
        if h == 1:
            return w
        if (h, w) in memo:
            return memo[(h, w)]

        ans = h * w  # Max possible is all 1x1 squares

        # Try all horizontal cuts
        for i in range(1, h // 2 + 1):
            ans = min(ans, dp(i, w) + dp(h - i, w))

        # Try all vertical cuts
        for j in range(1, w // 2 + 1):
            ans = min(ans, dp(h, j) + dp(h, w - j))

        # Try placing a square of size k at a corner
        for k in range(1, h):
            # Place k x k at the corner, leaving two rectangles
            # 1. h x (w - k) and (h - k) x k
            ans = min(ans, dp(k, w - k) + dp(h - k, w) + 1)
            # 2. (h - k) x w and h x (w - k) -> wait, standard partitioning:
            ans = min(ans, dp(h - k, w) + dp(h, k - w) if k > w else float('inf'))
            # More generally, try placing square of size k (1 <= k < min(h, w))
            # Cut into: square k x k, and remaining parts.
            # Actually, standard guillotine + square placement:
            for i in range(1, h):
                pass

        # Simpler robust version of square placement:
        for k in range(1, min(h, w)):
            # Place k x k square
            # Remaining area can be split into valid sub-problems
            # We can try all partitions formed by a square of size k
            ans = min(ans, 1 + dp(k, w - k) + dp(h - k, w))
            ans = min(ans, 1 + dp(h - k, k) + dp(h, w - k))

        memo[(h, w)] = ans
        return ans

    print(dp(n, m))

