def numberOfPath(n, k, arr):
    # dp[i][j][s] represents the number of paths to cell (i, j) with sum s
    # Using a 3D array of size n x n x (k + 1)
    dp = [[[0 for _ in range(k + 1)] for _ in range(n)] for _ in range(n)]

    # Base case
    if arr[0][0] <= k:
        dp[0][0][arr[0][0]] = 1

    for i in range(n):
        for j in range(n):
            for s in range(k + 1):
                if dp[i][j][s] > 0:
                    # Move right
                    if j + 1 < n and s + arr[i][j + 1] <= k:
                        dp[i][j + 1][s + arr[i][j + 1]] += dp[i][j][s]
                    # Move down
                    if i + 1 < n and s + arr[i + 1][j] <= k:
                        dp[i + 1][j][s + arr[i + 1][j]] += dp[i][j][s]

    return dp[n - 1][n - 1][k]

