def printFibb(n):
    if n <= 0:
        return []
    if n == 1:
        return [1]

    # Initialize the DP table with the first two Fibonacci numbers
    dp = [0] * n
    dp[0] = 1
    dp[1] = 1

    # Fill the DP table iteratively
    for i in range(2, n):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp

