    if not data:
        return

    t = int(data[0])
    queries = [int(x) for x in data[1:]]

    max_n = max(queries)

    # Precompute DP up to the maximum possible query or up to 10^6
    limit = min(max_n, 1000000)
    dp = [False] * (limit + 1)
    dp[0] = True

    for i in range(limit + 1):
        if dp[i]:
            if i + 2020 <= limit:
                dp[i + 2020] = True
            if i + 2021 <= limit:
                dp[i + 2021] = True

    out = []
    for n in queries:
        if n <= limit and dp[n]:
            out.append("YES")
        else:
            # Mathematical shortcut for values > 10^6:
            # Any number >= 2020 * 2020 can be formed, or more simply check remainder
            # But since max_n <= 10^6, the DP table covers all queries.
            # For any n > 10^6 (if max_n exceeded limit), we can use: n % 2020 <= n // 2020
            if n > limit:
                # n = 2020 * k + r. Can we use r copies of 2021 to cover r? 
                # We need r * 2021 = ... wait, 2021 = 2020 + 1, so r * 2021 = r * 2020 + r.
                # Thus n = 2020 * (k + r) + r. This works if r <= k (i.e., n % 2020 <= n // 2020).
                q = n // 2020
                r = n % 2020
                if r <= q:
                    out.append("YES")
                else:
                    out.append("NO")
            else:
                out.append("NO")

    print('\n'.join(out))

