class Solution:
    def DivisibleByM(self, nums, m):
        n = len(nums)
        # dp[r] will store whether remainder r is possible
        # Initialize all remainders as False except 0
        dp = [False] * m

        for x in nums:
            rem = x % m
            if rem == 0:
                return 1

            # Create a new dp state to avoid using the same element multiple times in one step
            next_dp = list(dp)
            next_dp[rem] = True

            for r in range(m):
                if dp[r]:
                    next_dp[(r + rem) % m] = True

            dp = next_dp
            if dp[0]:
                return 1

        return 1 if dp[0] else 0

