import sys

def findShortestPath(mat):
    if not mat or not mat[0]:
        return -1

    R = len(mat)
    C = len(mat[0])

    # Directions for 4-way movement
    dRow = [-1, 0, 1, 0]
    dCol = [0, 1, 0, -1]

    # Step 1: Mark all adjacent cells of landmines as unsafe
    for i in range(R):
        for j in range(C):
            if mat[i][j] == 0:
                for k in range(4):
                    ni, nj = i + dRow[k], j + dCol[k]
                    if 0 <= ni < R and 0 <= nj < C:
                        # Mark as temporarily unsafe if it was originally 1
                        if mat[ni][nj] == 1:
                            mat[ni][nj] = -1

    # Update temporary unsafe cells to actual blocked (0)
    for i in range(R):
        for j in range(C):
            if mat[i][j] == -1:
                mat[i][j] = 0

    # Step 2: Initialize BFS
    queue = deque()
    visited = [[False * C for _ in range(C)] for _ in range(R)] # wait, correctly size visited
    visited = [[False] * C for _ in range(R)]

    # Push all safe cells in the first column
    for i in range(R):
        if mat[i][0] == 1:
            queue.append((i, 0, 1))
            visited[i][0] = True
        elif mat[i][0] == 0:
            visited[i][0] = True # effectively blocked

    # Step 3: BFS Traversal
    while queue:
        r, c, dist = queue.popleft()

        if c == C - 1:
            return dist

        for k in range(4):
            nr, nc = r + dRow[k], c + dCol[k]
            if 0 <= nr < R and 0 <= nc < C and mat[nr][nc] == 1 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1

