            queue.append((i, 0, 1))
            visited[i][0] = True
        elif mat[i][0] == 0:
            visited[i][0] = True # effectively blocked

    # Step 3: BFS Traversal
    while queue:
        r, c, dist = queue.popleft()

        if c == C - 1:
            return dist

        for k in range(4):
            nr, nc = r + dRow[k], c + dCol[k]
            if 0 <= nr < R and 0 <= nc < C and mat[nr][nc] == 1 and not visited[nr][nc]:
                visited[nr][nc] = True
                queue.append((nr, nc, dist + 1))

    return -1

