class Solution:
    def possible_paths(self, edges, n, s, d):
        # Build adjacency list
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)

        memo = {}

        def dfs(curr):
            if curr == d:
                return 1
            if curr in memo:
                return memo[curr]

            total_paths = 0
            for neighbor in adj[curr]:
                total_paths += dfs(neighbor)

            memo[curr] = total_paths
            return total_paths

        return dfs(s)

