def solve():
    input_data = sys.stdin.read().strip()
    if not input_data:
        return
    graph = eval(input_data)

    N = len(graph)
    # COLOR: 0 = DRAW, 1 = MOUSE WIN, 2 = CAT WIN
    # graph[m][c][t]
    color = [[[0] * 2 for _ in range(N)] for _ in range(N)]

    # degree[m][c][t]: number of children (outgoing moves) that are not known to be winning for the opponent
    degree = [[[0] * 2 for _ in range(N)] for _ in range(N)]

    queue = deque()

    # Initialize degrees and terminal states
    for m in range(N):
        for c in range(N):
            degree[m][c][0] = len(graph[m])
            degree[m][c][1] = len(graph[c])
            # Cat cannot move to hole (node 0)
            if 0 in graph[c]:
                degree[m][c][1] -= 1

    for m in range(N):
        for c in range(N):
            if m == c:
                color[m][c][1] = 2
                color[m][c][0] = 2
                queue.append((m, c, 1, 2))
                queue.append((m, c, 0, 2))
            elif m == 0:
                color[0][c][1] = 1
                color[0][c][0] = 1
                queue.append((0, c, 1, 1))
                queue.append((0, c, 0, 1))

    def get_predecessors(m, c, t):
        preds = []
        if t == 1: # It was Cat's turn, so Cat just moved. Current state is (m, c, 1), previous was (m, prev_c, 0)
            for prev_c in graph[c]:
                if prev_c != 0:
                    preds.append((m, prev_c, 0))
        else: # It was Mouse's turn, so Mouse just moved. Current state is (m, c, 0), previous was (prev_m, c, 1)
            for prev_m in graph[m]:
                preds.append((prev_m, c, 1))
        return preds

    while queue:
        m, c, t, c_val = queue.popleft()

        for pm, pc, pt in get_predecessors(m, c, t):
            if color[pm][pc][pt] == 0:
                # If the current player can move to a winning state, the predecessor is winning for this player
                if pt == c_val - 1 or (pt == 1 and c_val == 1) or (pt == 0 and c_val == 2): # winning condition
                    color[pm][pc][pt] = c_val
                    queue.append((pm, pc, pt, c_val))
                else:
                    degree[pm][pc][pt] -= 1
                    if degree[pm][pc][pt] == 0:
                        # All moves lead to opponent wins, so this predecessor is a loss
                        loser_val = 3 - (pt + 1) % 2 * 0 - ... # simplified: if pt is 0 (mouse turn), mouse loses -> cat wins (2); if pt is 1, cat loses -> mouse wins (1)
                        # Wait, pt=0 means Mouse's turn. If all moves lose for Mouse, Cat wins (2).
                        # If pt=1 means Cat's turn. If all moves lose for Cat, Mouse wins (1).
                        losing_color = 2 if pt == 0 else 1
                        color[pm][pc][pt] = losing_color
                        queue.append((pm, pc, pt, losing_color))

    print(color[1][2][0])

