class Solution:
    def countDistinctIslands(self, grid: list[list[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        visited = [[False * m for _ in range(m)] for _ in range(n)]
        distinct_islands = set()

        def dfs(r, c, base_r, base_c, current_shape):
            visited[r][c] = True
            # Record the relative position from the starting cell of the island
            current_shape.append((r - base_r, c - base_c))

            # 4 possible directions: up, down, left, right
            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == 1:
                    dfs(nr, nc, base_r, base_c, current_shape)

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1 and not visited[i][j]:
                    shape = []
                    dfs(i, j, i, j, shape)
                    # Convert list to tuple so it can be added to a set
                    distinct_islands.add(tuple(shape))

        return len(distinct_islands)

