class Solution:
    def helpaterp(self, hospital):
        if not hospital or not hospital[0]:
            return 0

        R = len(hospital)
        C = len(hospital[0])

        queue = deque()
        fresh_count = 0

        # Initialize queue with all multi-sources (infected patients) and count fresh patients
        for i in range(R):
            for j in range(C):
                if hospital[i][j] == 2:
                    queue.append((i, j, 0))
                elif hospital[i][j] == 1:
                    fresh_count += 1

        if fresh_count == 0:
            return 0

        max_time = 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Multi-source BFS
        while queue:
            r, c, time = queue.popleft()
            max_time = max(max_time, time)

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and hospital[nr][nc] == 1:
                    hospital[nr][nc] = 2
                    fresh_count -= 1
                    queue.append((nr, nc, time + 1))

        return max_time if fresh_count == 0 else -1

