def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    out = []

    for _ in range(t):
        n = int(data[idx])
        p = int(data[idx+1])
        idx += 2

        edges = set()
        # Base graph: connect i to (i % n) + 1 and ((i + 1) % n) + 1
        # 1-indexed vertices
        for i in range(1, n + 1):
            nxt1 = i % n + 1
            nxt2 = (i + 1) % n + 1
            edges.add((min(i, nxt1), max(i, nxt1)))
            edges.add((min(i, nxt2), max(i, nxt2)))

        # We need p more edges. We can add them between vertex 1 and others, or any valid pairs.
        # Let's add edges between vertex 1 and i (for i from 4 to n) until we have p extra edges.
        added = 0
        for i in range(4, n + 1):
            if added == p:
                break
            edge = (min(1, i), max(1, i))
            if edge not in edges:
                edges.add(edge)
                added += 1

        # If still need more edges (though usually p is small or covered by the above)
        if added < p:
            for i in range(1, n + 1):
                if added == p:
                    break
                for j in range(i + 1, n + 1):
                    if added == p:
                        break
                    edge = (i, j)
                    if edge not in edges:
                        edges.add(edge)
                        added += 1

        for u, v in edges:
            out.append(f"{u} {v}")

    print('\n'.join(out))

