def minimum_number(s):
    # Count frequencies of each digit '0'-'9'
    counts = [0] * 10
    for char in s:
        counts[ord(char) - ord('0')] += 1

    # Find the smallest non-zero digit to be the leading digit
    first_digit = 0
    for i in range(1, 10):
        if counts[i] > 0:
            first_digit = i
            break

    # Build the resulting string
    res = [str(first_digit)]
    counts[first_digit] -= 1

    # Append remaining digits in ascending order
    for i in range(10):
        if counts[i] > 0:
            res.append(str(i) * counts[i])

    return "".join(res)

