        suff = [0] * (4 * N)
        left_val = [0] * (4 * N)
        right_val = [0] * (4 * N)
        length = [0] * (4 * N)

        def push_up(node):
            lc = 2 * node
            rc = 2 * node + 1
            length[node] = length[lc] + length[rc]
            left_val[node] = left_val[lc]
            right_val[node] = right_val[rc]

            # pref
            if pref[lc] == length[lc] and left_val[rc] > right_val[lc]:
                pref[node] = pref[lc] + pref[rc]
            else:
                pref[node] = pref[lc]

            # suff
            if suff[rc] == length[rc] and right_val[lc] < left_val[rc]:
                suff[node] = suff[rc] + suff[lc]
            else:
                suff[node] = suff[rc]

            # ans
            res = max(ans[lc], ans[rc])
            if right_val[lc] < left_val[rc]:
                res = max(res, suff[lc] + pref[rc])
            ans[node] = res

        def build(node, l, r):
            if l == r:
                ans[node] = 1
                pref[node] = 1
                suff[node] = 1
                left_val[node] = P[l]
                right_val[node] = P[l]
                length[node] = 1
                return
            mid = (l + r) // 2
            build(2 * node, l, mid)
            build(2 * node + 1, mid + 1, r)
            push_up(node)

        def update(node, l, r, idx_pos, val):
            if l == r:
                P[l] += val
                left_val[node] = P[l]
                right_val[node] = P[l]
                return
            mid = (l + r) // 2
            if idx_pos <= mid:
                update(2 * node, l, mid, idx_pos, val)
            else:
                update(2 * node + 1, mid + 1, r, idx_pos, val)
            push_up(node)

        def query(node, l, r, ql, qr):
            if ql <= l and r <= qr:
                return node
            mid = (l + r) // 2
            if qr <= mid:
                return query(2 * node, l, mid, ql, qr)
            elif ql > mid:
                return query(2 * node + 1, mid + 1, r, ql, qr)
            else:
                left_res = query(2 * node, l, mid, ql, qr)
                right_res = query(2 * node + 1, mid + 1, r, ql, qr)

                # Combine left_res and right_res
                res_ans = max(ans[left_res], ans[right_res])
                if right_val[left_res] < left_val[right_res]:
                    res_ans = max(res_ans, suff[left_res] + pref[right_res])

                # We need to construct a temporary node or just return the combined values.
                # To make it simple, we can return a tuple or use a separate combination function.
                # Let's write a helper function to combine two nodes (or node IDs).
                return combine(left_res, right_res)

        def combine(lc, rc):
            # Returns a virtual node representation or we can just compute it directly.
            # Actually, standard segment tree query can return an object or we can use a small class/dict/list.
            pass

        # Due to python recursion limit and segment tree query complexity for partial overlaps,
        # let's use an explicit query function returning (ans, pref, suff, left_val, right_val, length)

        def query_val(node, l, r, ql, qr):
            if ql <= l and r <= qr:
                return (ans[node], pref[node], suff[node], left_val[node], right_val[node], length[node])
            mid = (l + r) // 2
            if qr <= mid:
                return query_val(2 * node, l, mid, ql, qr)
            elif ql > mid:
                return query_val(2 * node + 1, mid + 1, r, ql, qr)
            else:
                a_ans, a_pref, a_suff, a_lv, a_rv, a_len = query_val(2 * node, l, mid, ql, qr)
                b_ans, b_pref, b_suff, b_lv, b_rv, b_len = query_val(2 * node + 1, mid + 1, r, ql, qr)

                res_len = a_len + b_len
                res_lv = a_lv
                res_rv = b_rv

                if a_pref == a_len and a_rv < b_lv:
                    res_pref = a_pref + b_pref
                else:
                    res_pref = a_pref

                if b_suff == b_len and a_rv < b_lv:
