                else:
                    res_suff = b_suff

                res_ans = max(a_ans, b_ans)
                if a_rv < b_lv:
                    res_ans = max(res_ans, a_suff + b_pref)

                return (res_ans, res_pref, res_suff, res_lv, res_rv, res_len)

        build(1, 1, N)

        for _ in range(Q):
