class Solution:
    def findSubString(self, s: str) -> int:
        if not s:
            return 0

        # Find all distinct characters in the string
        required_chars = set(s)
        required_count = len(required_chars)

        # Dictionary or array to store frequencies of characters in the current window
        window_counts = {}

        left = 0
        formed = 0
        min_len = float('inf')

        for right in range(len(s)):
            char = s[right]
            window_counts[char] = window_counts.get(char, 0) + 1

            # If the current character's frequency matches its presence requirement
            if window_counts[char] == 1:
                formed += 1

            # Contract the window as much as possible while it remains valid
            while left <= right and formed == required_count:
                min_len = min(min_len, right - left + 1)

                left_char = s[left]
                window_counts[left_char] -= 1
                if window_counts[left_char] == 0:
                    formed -= 1

                left += 1

        return min_len if min_len != float('inf') else 0

