def sentenceWord(text):
    sentences = 0
    words = 0
    in_word = False
    has_sentence_content = False

    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        # Check for word character
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z'):
            has_sentence_content = True
            if not in_word:
                in_word = True
                words += 1
        else:
            in_word = False

        # Check for sentence ending punctuation
        if ch in ['.', '!', '?']:
            if has_sentence_content:
                sentences += 1
                has_sentence_content = False

        i += 1

    # If there is remaining text without ending punctuation, it forms the last sentence
    if has_sentence_content:
        sentences += 1

