class Solution:
    def largestSubsquare(self, N, A):
        # Create auxiliary tables for horizontal and vertical counts of 'X'
        hor = [[0] * N for _ in range(N)]
        ver = [[0] * N for _ in range(N)]

        # Fill hor and ver tables
        for i in range(N):
            for j in range(N):
                if A[i][j] == 'X':
                    hor[i][j] = hor[i][j-1] + 1 if j > 0 else 1
                    ver[i][j] = ver[i-1][j] + 1 if i > 0 else 1
                else:
                    hor[i][j] = 0
                    ver[i][j] = 0

        max_size = 0

        # Iterate over all possible bottom-right corners of the subsquare
        for i in range(N):
            for j in range(N):
                # Find the maximum possible side length based on current cell's hor and ver
                small = min(hor[i][j], ver[i][j])

                # If the current possible size is smaller than the max found so far, skip
                if small <= max_size:
                    continue

                # Try decreasing sizes from 'small' down to max_size + 1
                for k in range(small, max_size, -1):
                    # Check the top and left boundaries of the square of size k
                    # Top-left corner is at (i - k + 1, j - k + 1)
                    if ver[i][j - k + 1] >= k and hor[i - k + 1][j] >= k:
                        max_size = max(max_size, k)
                        break

        return max_size

