def isWin(board, char):
    win_patterns = [
        (0, 1, 2), (3, 4, 5), (6, 7, 8),  # Rows
        (0, 3, 6), (1, 4, 7), (2, 5, 8),  # Columns
        (0, 4, 8), (2, 4, 6)             # Diagonals
    ]
    for p in win_patterns:
        if board[p[0]] == char and board[p[1]] == char and board[p[2]] == char:
            return True
    return False

def isValid(board):
    x_count = board.count('X')
    o_count = board.count('O')

    # Condition 1: O's count can't be greater than X's count, 
    # and X can't have more than one extra move.
    if x_count < o_count or x_count - o_count > 1:
        return False

    x_win = isWin(board, 'X')
    o_win = isWin(board, 'O')

    # Condition 2: Both players cannot win simultaneously.
    if x_win and o_win:
        return False

    # Condition 3: If X wins, X must have made the last move (count(X) > count(O))
    if x_win and x_count == o_count:
        return False

    # Condition 4: If O wins, O must have made the last move (count(X) == count(O))
    if o_win and x_count != o_count:
        return False

    return True

