class Solution:
    def isCircular(self, path: str) -> str:
        # Directions: 0: North, 1: East, 2: South, 3: West
        dx = [0, 1, 0, -1]
        dy = [1, 0, -1, 0]

        x, y = 0, 0
        direction = 0  # Initially facing North

        for move in path:
            if move == 'L':
                direction = (direction + 3) % 4
            elif move == 'R':
                direction = (direction + 1) % 4
            elif move == 'G':
                x += dx[direction]
                y += dy[direction]

        if x == 0 and y == 0:
            return "Circular"
        else:
            return "Not Circular"

