class Solution:
    def singlevalued(self, root):
        self.count = 0

        def dfs(node):
            if not node:
                return True, None

            left_is_single, left_val = dfs(node.left)
            right_is_single, right_val = dfs(node.right)

            is_single = True

            if not left_is_single:
                is_single = False
            if not right_is_single:
                is_single = False

            if left_val is not None and left_val != node.data:
                is_single = False
            if right_val is not None and right_val != node.data:
