            if is_single:
                self.count += 1

            return is_single, node.data

        dfs(root)
        return self.count

class TrieNode:
    def __init__(self):
        self.children = {}
        self.words = []

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, upper_seq, original_word):
        node = self.root
        for char in upper_seq:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.words.append(original_word)

    def search(self, pattern):
        node = self.root
        for char in pattern:
            if char not in node.children:
                return []
            node = node.children[char]
        return node.words

def CamelCase(N, Dictionary, Pattern):
    trie = Trie()

    # Sort dictionary first to maintain lexicographical order
    Dictionary.sort()

    for word in Dictionary:
        upper_seq = "".join([c for c in word if c.isupper()])
        trie.insert(upper_seq, word)

    result = trie.search(Pattern)
    return result if result else [-1]

