def nextRight(root, key):
    if not root:
        return Node(-1)
    
    queue = deque([root])
    
    while queue:
        level_size = len(queue)
        
        for i in range(level_size):
            curr = queue.popleft()
            
            # If this is the node with the given key
            if curr.data == key:
                # If it's not the last node in the current level, return the next node in the queue
                if i < level_size - 1:
                    return queue[0]
                else:
                    return Node(-1)
            
            if curr.left:
                queue.append(curr.left)
            if curr.right:
                queue.append(curr.right)
                
    return Node(-1)

