class Solution:
    def maxLevelSum(self, root):
        if not root:
            return 0

        max_sum = -float('inf')
        queue = deque([root])

        while queue:
            level_size = len(queue)
            current_level_sum = 0

            for _ in range(level_size):
                node = queue.popleft()
                current_level_sum += node.data

                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            if current_level_sum > max_sum:
                max_sum = current_level_sum

        return max_sum

# Helper function to build tree from level order string representation
def build_tree(s):
    if not s or s[0] == "N":
        return None
    ip = s.split()
    root = Node(int(ip[0]))
    queue = deque([root])
    i = 1
    while queue and i < len(ip):
        curr_node = queue.popleft()
        curr_val = ip[i]
        if curr_val != "N":
            curr_node.left = Node(int(curr_val))
            queue.append(curr_node.left)
        i += 1
        if i >= len(ip):
            break
        curr_val = ip[i]
        if curr_val != "N":
            curr_node.right = Node(int(curr_val))
            queue.append(curr_node.right)
        i += 1
    return root

