def are_anagrams(str1: str, str2: str) -> bool:
    # Normalize strings to lowercase to make the check case-insensitive
    s1 = str1.lower()
    s2 = str2.lower()

    # If lengths differ, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Count character frequencies
    count = {}
    for char in s1:
        count[char] = count.get(char, 0) + 1

    for char in s2:
        if char not in count or count[char] == 0:
            return False
        count[char] -= 1

    return True

