    def find_subsequence(target):
        # Returns the starting index of the earliest match of the subsequence 'target' in lower_meme, or infinity if not found.
        it_target = iter(target)
        first_char = next(it_target)
        try:
            start_pos = lower_meme.index(first_char)
        except ValueError:
            return float('inf')

        curr_pos = start_pos
        for char in it_target:
            try:
                curr_pos = lower_meme.index(char, curr_pos + 1)
            except ValueError:
                return float('inf')
        return start_pos

    # Keywords and their corresponding receivers
    matches = [
        (find_subsequence('bug'), "IT - 'Roma'"),
