def insertMissingLetters(s: str) -> str:
    present = set(s)
    alphabet = [chr(i) for i in range(ord('a'), ord('z') + 1)]

    seen = set()
    result = []

    for char in s:
        result.append(char)
        if char not in seen:
            seen.add(
                char
            )
            # Find missing letters that come after 'char'
            missing_after = [
                l.upper()
                for l in alphabet
                if l not in present and l > char
            ]
            result.extend(missing_after)

    return "".join(result)

