def countTwosAtDigitPosition(n, p):
    if n < p:
        return 0
    left = n // (p * 10)
    cur = (n // p) % 10
    right = n % p

    count = left * p
    if cur > 2:
        count += p
    elif cur == 2:
        count += right + 1
    return count

def countTwos(n):
    if n <= 0:
        return 0
    total_twos = 0
    p = 1
    while n // p > 0:
        total_twos += countTwosAtDigitPosition(n, p)
        p *= 10
    return total_twos

