    digit_count = [0] * 10
    prime_found = False

    for num in range(L, R + 1):
        if is_prime(num):
            prime_found = True
            temp = num
            while temp > 0:
                digit_count[temp % 10] += 1
                temp //= 10

    if not prime_found:
        return -1

    max_freq = -1
    best_digit = -1

    for digit in range(10):
        if digit_count[digit] >= max_freq:
            max_freq = digit_count[digit]
            best_digit = digit

    return best_digit

