class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def multiplyTwoLists(first, second):
    MOD = 10**9 + 7

    num1 = 0
    curr = first
    while curr:
        num1 = (num1 * 10 + curr.data) % MOD
        curr = curr.next

    num2 = 0
    curr = second
    while curr:
        num2 = (num2 * 10 + curr.data) % MOD
        curr = curr.next

    return (num1 * num2) % MOD

