def sieve(n):
	prime = [True for i in range(n + 1)]
	p = 2
	ret = []
	while p * p <= n:
		if prime[p]:
			for i in range(p ** 2, n + 1, p):
				prime[i] = False
		p += 1
	prime[0] = False
	prime[1] = False
	for p in range(n + 1):
		if prime[p]:
			ret.append(p)
	return ret
