def primeSum(N: int) -> int:
    # Set of prime single-digit numbers
    prime_digits = {2, 3, 5, 7}
    total_sum = 0

    # Extract each digit using arithmetic operations
    while N > 0:
        digit = N % 10
        if digit in prime_digits:
            total_sum += digit
        N //= 10

    return total_sum

